def image(name,alt,cls='',eager=False):
 return f'<img src="{A}{name}.webp" alt="{html.escape(alt)}" class="{cls}" width="{DIMENSIONS[name][0]}" height="{DIMENSIONS[name][1]}" loading="{"eager" if eager else "lazy"}" decoding="async">'
