def stores(place):
 apple='<svg viewBox="0 0 24 28" aria-hidden="true"><path fill="currentColor" d="M18 14c0-3 2-4.5 3-5-1.5-2-4-2.3-5-2.3-2 0-3 1-4 1s-2.5-1-4-1C4 6.8 1 10 1 14c0 6 4 12 6.5 12 1.5 0 2-1 4-1s2.5 1 4 1c2 0 5-4 6-7-2-.8-3.5-2.8-3.5-5ZM16 0c-3 .2-5 2-5 5 3 .3 5-2 5-5Z"/></svg>'
 play='<svg viewBox="0 0 25 28" aria-hidden="true"><path fill="#a5d4a0" d="M1 1v26l13-13Z"/><path fill="#f4d675" d="m1 1 17 10-4 3Z"/><path fill="#ec8661" d="m1 27 17-10-4-3Z"/><path fill="#fff" d="m18 11 6 3-6 3-4-3Z"/></svg>'
 return f'<div class="actions"><a class="store" href="https://apps.apple.com/jp/app/id6775411516" data-store="apple" data-placement="{place}">{apple}<span><small>iPhone・iPad</small><strong>App Store</strong></span></a><a class="store" href="https://play.google.com/store/apps/details?id=com.gokakushakaiquest.app" data-store="google" data-placement="{place}">{play}<span><small>Android</small><strong>Google Play</strong></span></a></div>'
def download():return home.download()
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def preview(name,alt):return f'<a class="preview-link" href="{A}{name}.webp" data-preview="{html.escape(alt)}">{image(name,alt)}<span class="preview-hint">画像を大きく見る ↗</span></a>'
def course_numbers(cid):
 d=STATS['courses'][cid]
 return '<dl class="course-numbers">'+''.join(f'<div><dt>{label}</dt><dd>{d[key]:,}<small>{suffix}</small></dd></div>' for label,key,suffix in [('問題','questions','問'),('図鑑','atlasPages','ページ'),('学習','unitCount','単元')])+'</dl>'
def unit_section(cid,name):
 d=STATS['courses'][cid]
 groups=''.join(f'<details class="unit-group"><summary><span>{html.escape(g["name"])}</span><small>{len(g["units"]):,}単元 ＋</small></summary><ul>'+''.join(f'<li><span>{html.escape(u["title"])}</span><small>{u["questions"]:,}問</small></li>' for u in g['units'])+'</ul></details>' for g in d['domains'])
 return f'<section class="section unit-section" id="units"><div class="wrap"><div class="section-head"><div><span class="kicker">学べる内容を、数字と単元で。</span><h2>{name}の学習ガイド</h2></div><p>気になる分野を開いて、単元をチェック。<br>今の目標に合う学びを見つけましょう。</p></div>{course_numbers(cid)}<p class="count-note">2026年10月25日確認の統合版収録データ。無料・Pro対象を含みます。問題数は教材内の重複IDを除いた件数、図鑑は収録ページ数です。コース間で問題を共有する場合、各単元の問題数の合計とは一致しません。配信版・OSにより利用範囲が異なる場合があります。</p><div class="unit-groups">{groups}</div><div class="course-usage-note"><strong>この教材の利用実績について</strong><p>教材別の利用人数・学習回数は、現在の集計では分けて確認できません。未集計は利用がないという意味ではありません。</p><a href="/quest/#track-record">アプリ全体のダウンロード実績を見る ↗</a></div></div></section>'
