PAGES.append(render('/quest/','合格！Quest｜中学受験4科から資格・語学まで、ひとつのアプリに。','全12教材にイラスト図鑑。問題画像・イラスト解説・対応問題の読み上げ音声で、基礎から応用まで学べます。無料の問題から始め、学ぶほど広がる王国を育てよう。',main,faqs=FAQ))
for c in COURSES:
 cid,slug,name,group,headline,lead,topics,sample,use,tint=c
 source=next(x for x in ASSETS if x['course']==cid)
 b=f'<div class="wrap crumbs"><a href="/quest/">Quest</a> / <a href="/quest/#courses">教材一覧</a> / {name}</div><section class="detail-hero"><div class="wrap detail-grid"><div><span class="eyebrow">{GROUP[group]} / 合格！Quest 統合版</span><h1>{name}。<br>{headline}</h1><p>{lead}</p><div class="actions"><a class="button orange" href="#download">この教材をアプリで始める ↗</a><a class="button outline" href="#samples">教材の画像を見る ↓</a></div><p class="fine">{"運転免許教材は無料で学べます。" if group=="life" else "無料で試せる問題があります。追加問題などはProプランの対象です。"}</p></div><div class="detail-visual" style="--tint:{tint}">{image(cid+"-atlas",name+"の図鑑："+sample,eager=True)}</div></div></section><section class="section white"><div class="wrap"><div class="section-head"><div><span class="kicker">学べること</span><h2>{name}で学べること。</h2></div><p>まずは関心のある単元から。<br>図鑑・問題・解説で、知識を確かめます。</p></div><div class="topic-grid">'+''.join(f'<article class="topic"><h3>{t}</h3><p>{p}</p></article>' for t,p in topics)+'</div></div></section>'
 figures=f'<figure>{preview(cid+"-atlas",name+"の図鑑："+sample)}<figcaption>図鑑で、全体や関係を整理。<small>{sample}の教材例です。</small></figcaption></figure>'
 quizpath=ROOT/'assets/quest'/f'{cid}-quiz.webp'
 if quizpath.exists():figures+=f'<figure>{preview(cid+"-quiz",name+"の問題・解説の実画面")}<figcaption>問題を解いて、解説で確認。<small>アプリの学習画面の一例です。</small></figcaption></figure>'
 elif any(q['course']==cid for q in QUESTIONS):
  q=next(q for q in QUESTIONS if q['course']==cid)
  figures+=f'<figure>{preview(cid+"-question",name+"の問題用イラスト")}<figcaption>問題の場面を、イラストで。<small>{html.escape(q["question"])}</small></figcaption></figure>'
 else:figures+=f'<figure>{preview("step2-build","学習で得たコインで建物を選ぶ王国の実画面")}<figcaption>学んだあとは、王国づくり。<small>どの教材の学習も、街づくりにつながります。</small></figcaption></figure>'
 b+=unit_section(cid,name)+f'<section class="section" id="samples"><div class="wrap"><div class="section-head"><div><span class="kicker">教材の中身</span><h2>教材を、のぞいてみよう。</h2></div><p>実際に使われている教材画像を掲載。<br>タップすると大きく読めます。</p></div><div class="gallery two">{figures}</div><p class="fine" style="margin-top:15px">出典：合格！Questの{ name }教材。画像は一例であり、画像・イラスト解説・読み上げは対応問題で利用できます。教材や画面は更新により変わります。</p></div></section><section class="section mint"><div class="wrap split"><div><span class="kicker">毎日の使い方</span><h2>いつもの時間に、<br>学ぶ楽しみを。</h2></div><div><h3>こんな使い方から。</h3><p>{use}</p><a class="text-link" href="/quest/plans/">無料範囲とプランの選び方 ↗</a></div></div></section>'+(free() if group!='life' else '')+kingdom()+f'<section class="section"><div class="wrap"><div class="section-head"><h2>次の学びも、同じアプリで。</h2><a class="text-link" href="/quest/#courses">12教材をすべて見る ↗</a></div><div class="ccard-grid">'+''.join(card(x) for x in COURSES if x[3]==group and x[0]!=cid)+'</div></div></section>'
 PAGES.append(render(f'/quest/courses/{slug}/',f'{name}｜図鑑・問題・復習で学ぶ｜合格！Quest',lead,b,cid))
