for slug,title,headline,intro,selection in [('rika-shakai','中学受験の理科・社会','理科・社会の苦手を、<br>今日の「わかった」に。','塾で習ったことを、図鑑と短いクイズでもう一度。<br>覚えたつもりを確かめる、毎日の復習に。',COURSES[:2]),('school4','中学受験4科','4科の学びを、<br>ひとつの習慣に。','理科・社会・国語・算数を、ひとつのアプリで。<br>今日の宿題や苦手に合わせて、取り組む教科を選べます。',COURSES[:4])]:
 b=f'<section class="hero"><div class="wrap"><span class="eyebrow">中学受験・小学生の家庭学習</span><h1>{headline}</h1><p class="hero-lead">{intro}</p><div class="actions"><a class="button orange" href="#download">無料の問題から始める ↗</a><a class="button outline" href="#subjects">教材を見る ↓</a></div></div></section><section class="section white" id="subjects"><div class="wrap"><div class="section-head"><h2>学びたい教科から。</h2><p>画像を選ぶと、詳しい教材紹介へ。</p></div><div class="ccard-grid">'+''.join(card(c) for c in selection)+'</div></div></section>'+learning()+quiz()+free()+kingdom()+'<section class="section white"><div class="wrap"><div class="section-head"><h2>教科別のくわしいガイド。</h2></div><p><a class="text-link" href="/quest/juken/science/">中学受験 理科アプリ ↗</a> <a class="text-link" href="/quest/juken/social/">社会アプリ ↗</a> <a class="text-link" href="/quest/juken/kokugo/">国語アプリ ↗</a> <a class="text-link" href="/quest/juken/math/">算数アプリ ↗</a> <a class="text-link" href="/quest/juken/anki/">暗記アプリ ↗</a></p></div></section>'+f'<section class="section"><div class="wrap"><span class="kicker">おうちの方へ</span><h2>今日、どんな発見があった？</h2><p style="margin:24px 0">学習履歴や正答率を一緒に見て、取り組んだ単元を振り返る。<br>正解した数だけでなく、考えたことや解き直したことも、毎日の会話に。</p><a class="button outline" href="/quest/plans/">1科目・4科プランを比べる ↗</a></div></section>'
 PAGES.append(render(f'/quest/{slug}/',title+'の復習を、図鑑とクイズで｜合格！Quest',title+'を図鑑とクイズで復習。教材画像や学び方、中学受験4科プランをご紹介します。',b))
plans=[('1科目から','1科目Pro','好きな教材を、じっくり。','1つの対象教材を学びたい方に。理科だけ、社会だけ、資格ひとつから始められます。'),('中学受験のご家庭に','中学受験4科Pro','理科・社会・国語・算数。','4教科を切り替えて使いたい方に。塾の復習や、毎日の家庭学習をまとめたいご家庭へ。'),('幅広く学びたい方に','全科目Pro','受験も、資格も、語学も。','購入画面に表示される対象教材を学べます。今後追加される教材の利用条件は、追加時の案内をご確認ください。')]
b='<section class="hero"><div class="wrap"><span class="eyebrow">料金・購入ガイド</span><h1>まずは無料で。<br>続けたい学びを選ぼう。</h1><p class="hero-lead">無料の問題で使い心地を確かめてから、<br>目的に合うプランをアプリでお選びください。</p></div></section><section class="section white"><div class="wrap"><div class="price-grid">'+''.join(f'<article class="price {"featured" if i==1 else ""}">{"<span class=\"recommend\">中学受験4科をまとめて</span>" if i==1 else ""}<span class="pill">{tag}</span><h3>{name}</h3><div class="amount">{summary}</div><p>{desc}</p><ul><li>月額・年額のプラン</li><li>価格と利用範囲は購入画面で確認</li><li>サブスクリプションは自動更新</li></ul><a class="button outline" href="#download">アプリでプランを確認 ↗</a></article>' for i,(tag,name,summary,desc) in enumerate(plans))+'</div><div class="note-box"><strong>購入前に、アプリに表示される価格をご確認ください。</strong><br>ストアの商品一覧には旧商品が掲載されることがあります。新規購入できる商品・価格と、現在のご契約の更新価格は異なる場合があります。OS・地域・契約状況に応じて、購入確定前の画面に表示される価格・期間・対象教材をご確認ください。</div><p class="fine">このサイトで決済は行いません。月額・年額の料金はアプリ内でご確認いただけます。運転免許教材は無料です。</p></div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="kicker">購入の前に</span><h2>安心して選ぶために。</h2></div></div>'+faq(FAQ+[('解約や契約の確認はどこでできますか？','iPhone・iPadはApp Storeのサブスクリプション管理、AndroidはGoogle Playの定期購入管理から確認・解約できます。アプリを削除しただけでは契約は解約されません。更新日や解約の反映時期は、ご契約のストアでご確認ください。')])+'</div></section>'
PAGES.append(render('/quest/plans/','無料範囲・料金・購入ガイド｜合格！Quest','合格！Questの1科目・中学受験4科・全科目Proの選び方、無料範囲、購入の復元と契約管理のご案内。',b))
b=f'<section class="hero"><div class="wrap"><span class="eyebrow">王国マップ・学びが街になる</span><h1>その一問が、<br>まだ見ぬ王国への一歩。</h1><p class="hero-lead">問題を解いて、コインを集めて、好きな建物を。<br>学習を重ねるたび、あなたの街の物語が進みます。</p><a class="button orange" href="#download">学んで、王国を育てよう ↗</a></div></section><section class="section kingdom"><div class="wrap"><div class="section-head"><div><span class="kicker">王国を探検</span><h2>小さな街から、<br><em>16の領地へ。</em></h2></div><p>王都のまわりには、港の町、森の里、湖の町、雪国、砂の国。ランクアップで領地がひらき、街づくりの舞台が広がります。</p></div><div class="qa-toggle" aria-label="王国の表示を切り替え"><button data-world-view="day-tablet" aria-pressed="true">街を近くで見る</button><button data-world-view="night-overview" aria-pressed="false">領地を見渡す</button></div><div class="kingdom-shot"><img data-world-image src="{A}kingdom-day-tablet.webp" alt="家やお店を建てた王国マップの実画面" loading="lazy"></div><p class="caption">開発環境で撮影したアプリ実画面です。街の発展状態の一例で、初期状態ではありません。</p></div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="kicker">遊び方</span><h2>学ぶ。つくる。また学ぶ。</h2></div><p>遊ぶためのコインは、学びから。<br>勉強と街づくりが、ひとつにつながります。</p></div><div class="flow">'+''.join(f'<article class="flow-card"><span class="num">0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate([('クイズでコインを集める','問題に正解すると、王国を育てるためのコインがたまります。どの教科の学習も、街づくりにつながります。'),('建物を選んで建てる','家・お店・公園など、好きな建物を選んで配置。問題に正解すると工事が進み、建物が完成していきます。'),('街の育ち方を楽しむ','人口・経済・魅力を見ながら街を発展させましょう。ランクアップで新しい領地がひらきます。')]))+f'</div></div></section><section class="section white"><div class="wrap"><div class="section-head"><div><span class="kicker">自分らしい街に</span><h2>どんな街にするかは、あなた次第。</h2></div></div><div class="gallery two"><figure>{preview("step2-build","王国の建物を選ぶ実画面")}<figcaption>家も、公園も。好きな建物を選ぶ。<small>暮らしやすい街、にぎやかな街。いろいろな組み合わせを試せます。</small></figcaption></figure><figure>{preview("step6-landmarks","金閣寺などの名所を選ぶ実画面")}<figcaption>世界の名所を、あなたの王国に。<small>金閣寺やピラミッドなど、学びでも出会う建物が街の楽しみに。</small></figcaption></figure></div><div class="note-box">自分で建てるほか、町長リカの「おまかせ」で街づくりを進める機能も。操作に迷ったら、アプリ内の「あそびかた」をご覧ください。掲載機能はiOS公開版を基準としています。Androidの対応状況は配信中のアプリでご確認ください。</div></div></section><section class="section mint"><div class="wrap split"><div><span class="kicker">だれでも、どこからでも</span><h2>子どもも、大人も。<br>学びの積み重ねが見える。</h2></div><div><p>受験の復習で育てても、資格の勉強で育てても。王国は「今日も学んだ」を目に見える形にする楽しみです。</p><a class="button" href="/quest/#courses">育てたい学びを探す ↗</a></div></div></section>'
PAGES.append(render('/quest/kingdom/','王国マップ｜学んで建てて、16の領地へ｜合格！Quest','クイズでコインを集め、家やお店、公園、世界の名所を建てよう。学ぶほど王国が育つ合格！Questの遊び方を実画面で紹介。',b))
import juken
for p in juken.build(dict(stores=stores,faq=faq,unit_section=unit_section,preview=preview,image=image,card=card,COURSES=COURSES,STATS=STATS,FAQ=FAQ)):
 PAGES.append(render(p['path'],p['title'],p['desc'],p['body'],faqs=p['faqs'],extra=p['extra']))
(ROOT/'docs/quest/pages.json').write_text(json.dumps(PAGES,ensure_ascii=False,indent=2)+'\n')
print(f'Rendered {len(PAGES)} Quest pages')
